/**
 * Runtime decoder for CAD line-art packs (generated by the glb2/pack2
 * pipeline). Each group carries int16-quantized segment endpoints plus one
 * baked-lighting shade byte per segment; instanced groups (props) also carry
 * scene-space 4x4 matrices so every instance can spin around its own axis.
 */

export interface CadGroup {
  /** xyz per vertex, 2 vertices per segment */
  pos: Float32Array;
  /** baked light response 0..1, one entry PER VERTEX (pairs share a value) */
  shade: Float32Array;
  count: number;
}

export interface CadModel {
  groups: Record<string, CadGroup>;
  /** column-major 4x4s, scene space */
  instances: Record<string, Array<{ name: string, m: number[] }>>;
}

interface PackedGroup { n: number, mn: number[], ext: number[], p: string, s: string }
interface Packed {
  groups: Record<string, PackedGroup>;
  instances: Record<string, Array<{ name: string, m: number[] }>>;
}

function bytes(b64: string): Uint8Array {
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

export function decodeCad(data: Packed): CadModel {
  const groups: Record<string, CadGroup> = {};
  for (const cat of Object.keys(data.groups)) {
    const g = data.groups[cat];
    const raw = bytes(g.p);
    const q = new Int16Array(raw.buffer, raw.byteOffset, g.n * 6);
    const sb = bytes(g.s);
    const pos = new Float32Array(g.n * 6);
    const shade = new Float32Array(g.n * 2);
    for (let i = 0; i < g.n * 2; i++) {
      for (let k = 0; k < 3; k++) {
        pos[i * 3 + k] = ((q[i * 3 + k] + 32767) / 65534) * g.ext[k] + g.mn[k];
      }
      shade[i] = sb[i >> 1] / 255;
    }
    groups[cat] = { pos, shade, count: g.n };
  }
  return { groups, instances: data.instances || {} };
}

// ---------------------------------------------------------------------------
// Solid CAD packs (scripts/ladybug-solid-pack.mjs)
// ---------------------------------------------------------------------------

export interface CadSolidGroup {
  /** int16 positions; world = pos * qs + qo, dequantized in the vertex shader */
  pos: Int16Array;
  qs: number[];
  qo: number[];
  /** int8 unit normals, crease-split at the pack stage */
  normal: Int8Array;
  /** uint8 Onshape part colour */
  color: Uint8Array;
  /** uint8 ray-traced ambient occlusion, 0 = buried, 255 = open sky */
  ao: Uint8Array;
  index: Uint16Array | Uint32Array;
  verts: number;
  /** triangles */
  count: number;
}

export interface CadSolidModel {
  groups: Record<string, CadSolidGroup>;
  /** every group is instanced; the airframe itself just has one instance */
  instances: Record<string, Array<{ name: string, m: number[] }>>;
}

interface SolidHeaderGroup {
  v: number; n: number; qs: number[]; qo: number[]; w: number;
  p: number; nr: number; c: number; a: number; i: number;
}

/**
 * Decodes the solid pack asset (public/ladybug-solid.bin, written by
 * scripts/ladybug-solid-pack.mjs).
 *
 * Nothing is converted here. The vertex data is already in the layout the GPU
 * wants — int16 positions, int8 normals, uint8 colour and occlusion — so the
 * decode is a handful of typed-array VIEWS onto the downloaded buffer, with no
 * copy and no Float32 expansion. That is the difference between a mesh this
 * size appearing immediately and blocking the main thread for a beat.
 */
export function decodeCadSolid(buf: ArrayBuffer): CadSolidModel {
  const head = new DataView(buf);
  const magic = String.fromCharCode(head.getUint8(0), head.getUint8(1), head.getUint8(2), head.getUint8(3));
  if (magic !== "LBS1") throw new Error("ladybug-solid.bin: bad magic");
  const headerLen = head.getUint32(4, true);
  const json = new TextDecoder().decode(new Uint8Array(buf, 8, headerLen));
  const data = JSON.parse(json) as {
    groups: Record<string, SolidHeaderGroup>;
    instances: Record<string, Array<{ name: string, m: number[] }>>;
  };
  const base = 8 + headerLen;

  const groups: Record<string, CadSolidGroup> = {};
  for (const cat of Object.keys(data.groups)) {
    const g = data.groups[cat];
    groups[cat] = {
      pos: new Int16Array(buf, base + g.p, g.v * 3),
      qs: g.qs,
      qo: g.qo,
      normal: new Int8Array(buf, base + g.nr, g.v * 3),
      color: new Uint8Array(buf, base + g.c, g.v * 3),
      ao: new Uint8Array(buf, base + g.a, g.v),
      index: g.w
        ? new Uint32Array(buf, base + g.i, g.n * 3)
        : new Uint16Array(buf, base + g.i, g.n * 3),
      verts: g.v,
      count: g.n,
    };
  }
  return { groups, instances: data.instances || {} };
}

// ---------------------------------------------------------------------------
// Shared line-geometry builder (used by the hero drone and the Boreas tour)
// ---------------------------------------------------------------------------
import { BufferAttribute, BufferGeometry, Color } from "three";

/**
 * Solid CAD group -> a geometry the solid material can shade, uploaded in the
 * packed integer formats. Normals, colour and occlusion are flagged normalized
 * so the GPU maps them back to their real ranges for free; positions are not,
 * because the material rescales them with the group's own quantization
 * constants (a single mad in the vertex shader).
 */
export function cadSolidGeo(cg: CadSolidGroup): BufferGeometry {
  const geo = new BufferGeometry();
  geo.setAttribute("position", new BufferAttribute(cg.pos, 3, false));
  geo.setAttribute("normal", new BufferAttribute(cg.normal, 3, true));
  geo.setAttribute("color", new BufferAttribute(cg.color, 3, true));
  geo.setAttribute("aAO", new BufferAttribute(cg.ao, 1, true));
  geo.setIndex(new BufferAttribute(cg.index, 1));
  return geo;
}

/**
 * CAD group -> line geometry with the baked shade in vertex colors.
 * Dark-side edges sink, lit edges bloom — the shading layer, at zero
 * per-frame cost. `warm` mixes a subtle brand wash by height.
 */
export function cadLineGeo(cg: CadGroup, tint: number, warm = 0, warmLoHex = 0xce2a7f, warmHiHex = 0x0eabcd): BufferGeometry {
  const geo = new BufferGeometry();
  geo.setAttribute("position", new BufferAttribute(cg.pos, 3));
  const base = new Color(tint);
  const warmLo = new Color(warmLoHex);
  const warmHi = new Color(warmHiHex);
  const c = new Color();
  const col = new Float32Array(cg.pos.length);
  const n = cg.count * 2;
  for (let i = 0; i < n; i++) {
    const sh = cg.shade[i];
    const k = 0.30 + 0.85 * sh;
    c.copy(base);
    if (warm > 0) {
      const y = cg.pos[i * 3 + 1];
      const t = Math.min(1, Math.max(0, (y + 0.6) / 1.25));
      c.lerp(t < 0.5 ? warmLo : warmHi, warm * Math.abs(t - 0.5) * 2);
    }
    col[i * 3] = c.r * k;
    col[i * 3 + 1] = c.g * k;
    col[i * 3 + 2] = c.b * k;
  }
  geo.setAttribute("color", new BufferAttribute(col, 3));
  return geo;
}
